import assert from 'node:assert/strict';
import {buildClientReportModel} from '../../../lib/credit-engine/client-report/adapter.ts';
import {validateClientReportModel,visibleTexts,internalCode,allFactors} from '../../../lib/credit-engine/client-report/validation.ts';
import {stable,id} from '../../../lib/credit-engine/explainability/common.ts';
import {renderReport} from './render.mjs';
export function checkClientExpectations(e,m){const ex=e.expectations,x=e.input,all=m.actionPlan.horizons.flatMap(h=>h.items);if(ex.status)assert.equal(m.hero.status,ex.status);if(ex.globalStop){assert.equal(m.hero.globalStop,true);assert.equal(m.productFit.primary.length,0);assert.equal(m.index.value.value,null);}if(ex.distinct){assert.ok(m.index.value.value>=800);assert.notEqual(m.readiness.level,'Высокая готовность');}if(ex.index!==undefined)assert.equal(m.index.value.value,ex.index);if(ex.capacity!==undefined)assert.equal(m.capacity.headline.value,ex.capacity);if(ex.capacityStatus)assert.equal(m.capacity.status,ex.capacityStatus);if(ex.noScenario)assert.ok(!m.capacity.details.some(c=>c.title==='Сценарный эквивалент'));
if(ex.claim){const c=x.explainability.claims.find(c=>c.claimCode===ex.claim);assert.ok(c);assert.ok(allFactors(m).some(f=>f.claimId===c.claimId));}if(ex.context){const ids=x.explainability.claims.filter(c=>c.claimKind==='CONTEXT'&&c.contextRelationIds.length).map(c=>c.claimId);assert.ok(ids.length);assert.ok(allFactors(m).some(f=>ids.includes(f.claimId)));}if(ex.data){assert.ok(m.dataQuality.length);assert.ok(m.dataQuality.every(f=>f.status.tone==='data'));}if(ex.product)assert.ok([...m.productFit.primary,...m.productFit.other].some(p=>p.family===ex.product));if(ex.aligned)assert.ok([...m.productFit.primary,...m.productFit.other].some(p=>p.requested==='Запрошенный продукт соответствует основным вариантам'));if(ex.misaligned)assert.ok([...m.productFit.primary,...m.productFit.other].some(p=>p.requested.includes('не соответствует')));if(ex.focus)assert.ok(m.actionPlan.horizons.find(h=>h.id===ex.focus).focusIds.length);if(ex.dependency)assert.ok(all.some(i=>i.prerequisites.length));if(ex.actionStatus)assert.ok(all.some(i=>i.status===ex.actionStatus));if(ex.overflow)assert.ok(all.length>m.actionPlan.horizons.reduce((n,h)=>n+h.focusIds.length,0));if(ex.monitor)assert.ok(m.actionPlan.monitoringIds.length);if(ex.rerun){const c=x.explainability.claims.find(c=>c.claimCode==='RERUN:'+ex.rerun);assert.ok(m.actionPlan.rerun.some(r=>r.claimId===c.claimId));}if(ex.noFakeRerun){assert.equal(m.actionPlan.rerun.length,0);assert.ok(!m.hero.cta.label.includes('Обновить'));}
if(ex.free){assert.equal(m.meta.entitlement,'FREE');assert.equal(m.technical.claimIds.length,0);assert.equal(m.index.value,null);assert.equal(m.actionPlan.horizons.length,0);}if(ex.full)assert.ok(m.index.value&&m.capacity.headline&&m.index.components.length===4);if(ex.recommendations)assert.ok(m.recommendations.primary.length);if(ex.plan)assert.ok(all.length);
if(ex.defect){const c=x.explainability.claims.find(c=>c.claimCode==='RISK-BKI-CURRENT-OVERDUE');assert.ok(c);assert.equal(c.severity,'MEDIUM');assert.ok(allFactors(m).some(f=>f.claimId===c.claimId));assert.ok(!x.explainability.claims.some(c=>c.claimCode==='RISK-BKI-HISTORICAL-DELINQUENCY'));assert.ok(!/DELINQUENCY_1_29|DELINQUENCY_30_59|DELINQUENCY_60_PLUS/.test(JSON.stringify(m)));}
assert.ok(m.primaryFactors.length<=5);assert.ok(m.productFit.primary.length<=3);assert.ok(m.actionPlan.focusIds.length<=5);assert.ok(visibleTexts(m).every(t=>!internalCode.test(t)));validateClientReportModel(x,m);
}
export function checkHtml(m,print=false){const html=renderReport(m,print),ids=[...html.matchAll(/\sid="([^"]+)"/g)].map(x=>x[1]);assert.equal(new Set(ids).size,ids.length,'Duplicate DOM ID');assert.equal((html.match(/<main\b/g)||[]).length,1);assert.equal((html.match(/<h1\b/g)||[]).length,1);assert.ok(!/role="button"|type="checkbox"/.test(html));if(m.meta.entitlement==='FULL'){assert.equal((html.match(/data-primary-cta/g)||[]).length,print?0:1);assert.ok(html.includes(m.capacity.disclaimer));assert.ok(html.includes('Контрольная точка Prescore'));for(const id of ['index','readiness','capacity','factors','financing','recommendations','plan','data','sources','full','methodology'])assert.ok(ids.includes(id),'Missing section '+id);if(print){assert.ok(!html.includes('<nav'));assert.ok(!html.includes('<button'));assert.ok(!html.includes('<details'));assert.ok(!internalCode.test(html));}}else{assert.ok(!html.includes('data-primary-cta'));for(const text of ['Учтено в индексе','/ 1000','/ месяц'])assert.ok(!html.includes(text));}return html;}
export function runClientReportPack(entries){return {total:entries.length,results:entries.map(e=>{try {const before=stable(e.input),m=buildClientReportModel(e.input,{entitlement:e.entitlement});checkClientExpectations(e,m);checkHtml(m);checkHtml(m,true);assert.equal(before,stable(e.input));return {caseId:e.caseId,description:e.description,result:'PASS',fingerprint:id('client-golden',stable(m))};}catch(err){return {caseId:e.caseId,description:e.description,result:'FAIL',error:err.message};}})};}
